/**
 * TASK: Route button events with e.getActionCommand().
 *
 * Five buttons -- "7", "8", "9", "CLR" and "OK" -- all share this one
 * listener. A button's action command is its text unless it was changed,
 * so e.getActionCommand() tells you which one was pressed WITHOUT looking
 * at the button objects at all.
 *
 * Complete actionPerformed:
 *   a digit ("7", "8" or "9") -- append it to the display label named
 *                                "display", but never let the display grow
 *                                past 6 characters (extra digits are dropped)
 *   "CLR"                     -- set the display back to ""
 *   "OK"                      -- remember the current display as the last
 *                                submitted entry, then clear the display
 *
 * Example: 7, 8, OK -> submitted() is "78" and the display is "" again.
 * Before anything is submitted, submitted() returns "".
 */
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class KeypadEntryPanel extends JPanel implements ActionListener {

    private final JLabel display = new JLabel("");
    private String lastSubmitted = "";

    public KeypadEntryPanel() {
        display.setName("display");
        add(display);
        for (String face : new String[] { "7", "8", "9", "CLR", "OK" }) {
            JButton button = new JButton(face);
            button.setName(face);
            button.addActionListener(this);
            add(button);
        }
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        // TODO: switch on e.getActionCommand() and handle digits, CLR and OK
    }

    public String display() {
        return display.getText();
    }

    public String submitted() {
        // TODO: return the entry captured by the most recent OK press
        return null;
    }
}

