public class KeypadEntryPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void press(java.awt.Container panel, String face) {
        java.awt.Component c = find(panel, face);
        if (c instanceof javax.swing.AbstractButton) {
            ((javax.swing.AbstractButton) c).doClick();
        }
    }

    public static void main(String[] args) {
        try {
            KeypadEntryPanel panel = new KeypadEntryPanel();
            check("display starts empty", "", panel.display());
            check("nothing submitted yet", "", panel.submitted());

            press(panel, "7");
            press(panel, "8");
            check("digits are appended", "78", panel.display());

            press(panel, "CLR");
            check("CLR wipes the display", "", panel.display());

            press(panel, "9");
            press(panel, "7");
            press(panel, "9");
            check("more digits", "979", panel.display());

            press(panel, "OK");
            check("OK captures the entry", "979", panel.submitted());
            check("OK clears the display", "", panel.display());

            for (int i = 0; i < 9; i++) {
                press(panel, "8");
            }
            check("the display stops at six characters", "888888", panel.display());

            press(panel, "OK");
            check("second submission replaces the first", "888888", panel.submitted());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

